package com.hospital.platform.iam.interfaces;
import com.hospital.platform.common.api.ApiResponse; import com.hospital.platform.common.error.ErrorCode; import com.hospital.platform.common.trace.TraceId; import org.springframework.core.Ordered; import org.springframework.core.annotation.Order; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice;
@Order(Ordered.HIGHEST_PRECEDENCE) @RestControllerAdvice public class AuthorizationExceptionHandler { @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ApiResponse<Void>> denied(){return ResponseEntity.status(HttpStatus.FORBIDDEN).body(ApiResponse.failure(ErrorCode.FORBIDDEN.code(),ErrorCode.FORBIDDEN.message(),TraceId.get()));} }
